package io.zipcoder.originwar.desktop;
import io.zipcoder.originwar.engine.RunEngine;
import io.zipcoder.originwar.model.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.api.condition.*;
import java.io.*;
import java.nio.file.*;
import java.nio.channels.FileChannel;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
class SurvivalPersistenceTest{
 @TempDir Path dir;
 GameState valid(){return new RunEngine(420).saveState();}
 @Test void physicalWorldAndKnowledgeRoundTrip()throws Exception{var s=valid();s.tick=20;s.revision=9;s.actionSerial=11;s.circuitPower[1]=false;s.knowledge.add("ethics");s.playedExchanges.add("archive");s.completedSpeech.add("archive:0");s.memoryTicks.put("archive",18);s.heard.add(new GameState.HeardContact("east","mechanical contact",19));s.actors.getFirst().awareness=GameState.Awareness.SEARCH;s.actors.getFirst().lastX=5;s.actors.getFirst().lastY=6;s.actors.getFirst().searchTicks=4;var store=new SaveStore(dir);store.begin(s);var a=new SaveStore(dir).load();assertEquals(2,a.schemaVersion);assertEquals(s.revision,a.revision);assertArrayEquals(s.publicSupplyCells,a.publicSupplyCells);assertArrayEquals(s.routeCosts,a.routeCosts);assertArrayEquals(s.circuitPower,a.circuitPower);assertEquals(s.inventory.stream().map(i->i.id+":"+i.power).toList(),a.inventory.stream().map(i->i.id+":"+i.power).toList());assertEquals(GameState.Awareness.SEARCH,a.actors.getFirst().awareness);assertEquals(18,a.memoryTicks.get("archive"));assertTrue(a.completedSpeech.contains("archive:0"));assertEquals("east",a.heard.getFirst().direction);}
 @Test void corruptPrimaryUsesSameRunsBackup()throws Exception{var store=new SaveStore(dir);var s=valid();store.begin(s);s.tick=1;s.revision=1;store.save(s);Files.writeString(store.activeDirectory().resolve("active.json"),"broken");var reopened=new SaveStore(dir);assertEquals(0,reopened.load().tick);assertTrue(reopened.usedBackup());}
 @Test void failedNewGamePreservesPreviousPointer()throws Exception{var store=new SaveStore(dir);store.begin(valid());String oldPointer=Files.readString(dir.resolve("active.run"));var broken=new SaveStore(dir){@Override protected void beforeActivate(String id)throws IOException{throw new IOException("Injected activation failure");}};var next=valid();next.seed=999;assertThrows(IOException.class,()->broken.begin(next));assertEquals(oldPointer,Files.readString(dir.resolve("active.run")));assertEquals(420,new SaveStore(dir).load().seed);}
 @Test void newRunsBackupNeverResurrectsPreviousExpedition()throws Exception{var store=new SaveStore(dir);store.begin(valid());var second=valid();second.seed=222;store.begin(second);Files.writeString(store.activeDirectory().resolve("active.json"),"broken");assertEquals(222,new SaveStore(dir).load().seed);}
 @Test void recordedDeathCannotRecoverLivingBackup()throws Exception{var store=new SaveStore(dir);var s=valid();store.begin(s);s.hp=0;s.dead=true;store.save(s);Files.writeString(store.activeDirectory().resolve("active.json"),"broken");assertThrows(SaveStore.EndedRunException.class,()->new SaveStore(dir).load());}
 @Test void newRunAfterDeathHasSeparateMarker()throws Exception{var store=new SaveStore(dir);var s=valid();store.begin(s);s.hp=0;s.dead=true;store.save(s);store.begin(valid());assertFalse(new SaveStore(dir).load().dead);}
 @Test void profileIsExclusivelyHeldAndReopens()throws Exception{try(var lease=ProfileLease.acquire(dir)){assertThrows(IOException.class,()->ProfileLease.acquire(dir));}try(var second=ProfileLease.acquire(dir)){assertNotNull(second);}}
 @Test void malformedUnicodeSettingsRecoverDefaults()throws Exception{Files.writeString(dir.resolve("settings.properties"),"voice="+"\\uZZZZ");var settings=assertDoesNotThrow(()->new SettingsStore(dir));assertEquals(.7f,settings.voice);settings.clearSpeech=true;settings.soundCaptions=false;settings.reducedDynamicRange=true;settings.conversationFrequency=1;settings.save();var a=new SettingsStore(dir);assertTrue(a.clearSpeech);assertFalse(a.soundCaptions);assertTrue(a.reducedDynamicRange);assertEquals(1,a.conversationFrequency);}
 @Test void malformedRememberedEventFailsBeforeEngineConstruction()throws Exception{var store=new SaveStore(dir);var s=valid();s.memoryTicks.put("reconnect",null);assertThrows(IOException.class,()->store.begin(s));}
 @Test void oldSchemaAndForgedEquipmentAreRejected()throws Exception{var s=valid();s.schemaVersion=1;assertThrows(IOException.class,()->SaveStore.validate(s));s.schemaVersion=2;s.inventory.removeIf(i->i.type==GameState.ItemType.PISTOL);assertThrows(IOException.class,()->SaveStore.validate(s));}
 @Test void asynchronousWriterNeverBlocksSubmissionOrAllowsSecondCommit()throws Exception{var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var store=new SaveStore(dir){@Override public void begin(GameState s)throws IOException{entered.countDown();try{release.await();}catch(InterruptedException e){throw new IOException(e);}super.begin(s);}};try(var writer=new SaveCoordinator(store)){assertTimeoutPreemptively(Duration.ofSeconds(1),()->assertTrue(writer.begin(valid())));assertTrue(entered.await(2,TimeUnit.SECONDS));assertEquals(SaveCoordinator.Status.WRITING,writer.status());assertFalse(writer.save(valid()));release.countDown();await(writer);assertEquals(SaveCoordinator.Status.READY,writer.status());}finally{release.countDown();}}
 @Test void failedWriteRetriesExactSnapshotWithoutResubmittingAction()throws Exception{var attempts=new ArrayList<GameState>();var store=new SaveStore(dir){boolean failed;@Override public void save(GameState s)throws IOException{attempts.add(s.copy());if(!failed){failed=true;throw new IOException("Injected full disk");}super.save(s);}};var run=new RunEngine(420);try(var writer=new SaveCoordinator(store)){writer.begin(run.saveState());await(writer);run.submit(PlayerAction.of(PlayerAction.Type.WAIT));var pending=run.saveState();writer.save(pending);pending.tick=999;await(writer);assertEquals(SaveCoordinator.Status.FAILED,writer.status());assertTrue(writer.error().contains("full disk"));assertTrue(writer.retry());await(writer);assertEquals(SaveCoordinator.Status.READY,writer.status());assertEquals(2,attempts.size());assertEquals(1,attempts.getFirst().tick);assertEquals(attempts.getFirst().combatRng,attempts.getLast().combatRng);assertEquals(attempts.getFirst().actionSerial,attempts.getLast().actionSerial);assertEquals(1,new SaveStore(dir).load().tick);}}
 @Test @EnabledOnOs(OS.WINDOWS) void briefDeleteSharingLockRetainsPrimaryAndBackup()throws Exception{var store=new SaveStore(dir);var s=valid();store.begin(s);s.tick=7;var path=store.activeDirectory().resolve("active.json");var lock=FileChannel.open(path,StandardOpenOption.READ,com.sun.nio.file.ExtendedOpenOption.NOSHARE_DELETE);try(var releaser=Executors.newSingleThreadScheduledExecutor()){releaser.schedule(()->{try{lock.close();}catch(IOException e){throw new UncheckedIOException(e);}},90,TimeUnit.MILLISECONDS);try{store.save(s);}finally{lock.close();}}assertEquals(7,new SaveStore(dir).load().tick);Files.writeString(path,"broken");assertEquals(0,new SaveStore(dir).load().tick);}
 static void await(SaveCoordinator writer)throws Exception{long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(5);while(writer.status()==SaveCoordinator.Status.WRITING&&System.nanoTime()<deadline)Thread.sleep(5);assertNotEquals(SaveCoordinator.Status.WRITING,writer.status());}
 @Test void malformedKnowledgeArraysRecoverBackupBeforeCopy()throws Exception{for(String field:List.of("rememberedTiles","blueprintTiles","publicSupplyCells")){Path profile=dir.resolve(field);var store=new SaveStore(profile);store.begin(valid());Path primary=store.activeDirectory().resolve("active.json");String payload=Files.readString(primary);var envelope=new com.badlogic.gdx.utils.JsonReader().parse(payload);var json=envelope.get("state");json.remove(field);if(field.equals("publicSupplyCells"))json.addChild(field,new com.badlogic.gdx.utils.JsonValue(com.badlogic.gdx.utils.JsonValue.ValueType.nullValue));else{var columns=new com.badlogic.gdx.utils.JsonValue(com.badlogic.gdx.utils.JsonValue.ValueType.array);for(int x=0;x<64;x++)columns.addChild(new com.badlogic.gdx.utils.JsonValue(com.badlogic.gdx.utils.JsonValue.ValueType.nullValue));json.addChild(field,columns);}Files.writeString(primary,envelope.toJson(com.badlogic.gdx.utils.JsonWriter.OutputType.json));var reopened=new SaveStore(profile);assertEquals(420,reopened.load().seed);assertTrue(reopened.usedBackup(),field);}}
 @Test void failedLoadCanBeDismissedButFailedWriteCannot()throws Exception{var store=new SaveStore(dir);try(var writer=new SaveCoordinator(store)){assertTrue(writer.load());await(writer);assertEquals(SaveCoordinator.Status.FAILED,writer.status());assertTrue(writer.dismissFailedLoad());assertEquals(SaveCoordinator.Status.READY,writer.status());}}
 @Test void profileLeaseExcludesASeparateJvmProcess()throws Exception{String java=Path.of(System.getProperty("java.home"),"bin","java.exe").toString();String classpath=Path.of(ProfileLease.class.getProtectionDomain().getCodeSource().getLocation().toURI())+File.pathSeparator+Path.of(LeaseProbe.class.getProtectionDomain().getCodeSource().getLocation().toURI());try(var lease=ProfileLease.acquire(dir)){assertEquals(2,probe(java,classpath));}assertEquals(0,probe(java,classpath));}
 int probe(String java,String classpath)throws Exception{var process=new ProcessBuilder(java,"-cp",classpath,LeaseProbe.class.getName(),dir.toString()).redirectErrorStream(true).start();if(!process.waitFor(10,TimeUnit.SECONDS)){process.destroyForcibly();fail("Profile probe failed to finish");}return process.exitValue();}
 public static class LeaseProbe{public static void main(String[] args)throws Exception{try(var lease=ProfileLease.acquire(Path.of(args[0]))){System.out.println("acquired");}catch(IOException locked){System.exit(2);}}}
 @Test void missingResourceCannotSilentlyBecomeDefaultOxygen()throws Exception{var store=new SaveStore(dir);var s=valid();s.reserve=200;store.begin(s);var primary=store.activeDirectory().resolve("active.json");var json=new com.badlogic.gdx.utils.JsonReader().parse(Files.readString(primary));json.get("state").remove("reserve");Files.writeString(primary,json.toJson(com.badlogic.gdx.utils.JsonWriter.OutputType.json));var reopened=new SaveStore(dir);assertEquals(200,reopened.load().reserve);assertTrue(reopened.usedBackup());}
}
